// A Bitwig Studio controller script that builds a score from data.
//
// GENERATED by score.py (the bitwig-track skill's example) from
// bitwig/template.control.js. Edit score.py or the template and regenerate;
// don't edit the generated script by hand. score.py fills in the API version,
// vendor, name, author, UUID, and the score itself.
//
// Add it under Settings > Controllers > Add controller > <vendor> > <name>.
// It does nothing until you press one of its buttons, which sit under the
// controller in Settings > Controllers, and act on the open project:
//
//   Build     tempo, tracks with their presets, sends, master glue, one launcher
//             clip per track in scene 1, and cue markers at the cues.
//             Safe to press again: tracks, devices, and markers it finds by name
//             are reused, and clips are rewritten. Every clip is set to the
//             score's full length, read back, and retried until it sticks.
//   Lengths   reports each scene-1 clip's length ("Pad: 100 beats").
//   Markers   only the cue markers.
//   Record    records scene 1 into the arranger from bar 1: stops the
//             transport, turns off pre-roll, arms arranger record, launches
//             scene 1, and stops, disarms, and returns to the arrangement once
//             the score has played.
//   Stop      stops the transport and disarms arranger record (a safety net).
//
// Every step is logged to the Controller Script Console (Settings >
// Controllers, the console icon on this controller); lines start with the
// script's name in brackets. The version below shows in the first line, so
// you can tell which script Bitwig has loaded.

loadAPI(/*@API@*/25);
host.setShouldFailOnDeprecatedUse(false);
var VERSION = "1.1 (clip lengths)";
var NAME = "@NAME@";
host.defineController("@VENDOR@", "@NAME@", "1.1", "@UUID@", "@AUTHOR@");
host.defineMidiPorts(0, 0);

var SCORE = /*@SCORE@*/null;

var TAG = "[" + NAME + "] ";
var MAX_TRACKS = 64, MAX_FX = 8, MAX_SENDS = 8, MAX_MARKERS = 64, MAX_MASTER_DEVICES = 16, KEYS = 128;
var POLL_MS = 50;

var app, transport, arranger, markers, trackBank, fxBank, master, masterDevices, sceneBank, clip, clipTrack;
var trackFirstDevice = [], fxFirstDevice = [];
var running = false;
var noteStarts = {};      // "x:y" of every note start in the cursor clip, from the step observer
var noteStartCount = 0;
var lengthSeen = false;   // the cursor clip reported a range since it last changed track

function log(s) { host.println(TAG + s); }
function say(s) { log(s); host.showPopupNotification(NAME + ": " + s); }

function init() {
  app = host.createApplication();
  transport = host.createTransport();
  arranger = host.createArranger();
  markers = arranger.createCueMarkerBank(MAX_MARKERS);
  trackBank = host.createMainTrackBank(MAX_TRACKS, MAX_SENDS, 1);
  fxBank = host.createEffectTrackBank(MAX_FX, 1);
  master = host.createMasterTrack(0);
  masterDevices = master.createDeviceBank(MAX_MASTER_DEVICES);
  sceneBank = trackBank.sceneBank();
  clip = host.createLauncherCursorClip(steps(), KEYS);
  clipTrack = clip.getTrack();

  transport.tempo().value().markInterested();
  transport.isPlaying().markInterested();
  transport.playPosition().markInterested();
  transport.isArrangerRecordEnabled().markInterested();
  transport.preRoll().markInterested();

  var i, j;
  for (i = 0; i < MAX_TRACKS; i++) {
    var t = trackBank.getItemAt(i);
    t.exists().markInterested();
    t.name().markInterested();
    t.clipLauncherSlotBank().getItemAt(0).hasContent().markInterested();
    var d = t.createDeviceBank(1).getItemAt(0);
    d.exists().markInterested();
    d.name().markInterested();
    trackFirstDevice.push(d);
  }
  for (i = 0; i < MAX_FX; i++) {
    var f = fxBank.getItemAt(i);
    f.exists().markInterested();
    f.name().markInterested();
    var fd = f.createDeviceBank(1).getItemAt(0);
    fd.exists().markInterested();
    fd.name().markInterested();
    fxFirstDevice.push(fd);
  }
  for (i = 0; i < MAX_MASTER_DEVICES; i++) {
    masterDevices.getItemAt(i).exists().markInterested();
    masterDevices.getItemAt(i).name().markInterested();
  }
  for (i = 0; i < MAX_MARKERS; i++) {
    var m = markers.getItemAt(i);
    m.exists().markInterested();
    m.name().markInterested();
    m.position().markInterested();
  }
  clipTrack.name().markInterested();
  clipTrack.name().addValueObserver(function () { lengthSeen = false; });
  // The clip's range: Bitwig drops sets on values nobody subscribed to, so
  // these must be observed from init() for Build to change a clip's length.
  var ranges = [clip.getPlayStart(), clip.getPlayStop(), clip.getLoopStart(), clip.getLoopLength()];
  for (i = 0; i < ranges.length; i++) {
    ranges[i].markInterested();
    ranges[i].addValueObserver(function () { lengthSeen = true; });
  }
  clip.isLoopEnabled().markInterested();
  clip.addStepDataObserver(function (x, y, state) {
    var key = x + ":" + y;
    if (state === 2) {
      if (!noteStarts[key]) { noteStarts[key] = true; noteStartCount++; }
    } else if (noteStarts[key]) {
      delete noteStarts[key];
      noteStartCount--;
    }
  });

  // Preferences, so the buttons sit under this controller in Settings > Controllers.
  var doc = host.getPreferences();
  var section = NAME;
  doc.getSignalSetting("Build the score", section, "Build").addSignalObserver(function () { run("build", buildSteps()); });
  doc.getSignalSetting("Check clip lengths", section, "Lengths").addSignalObserver(function () { run("lengths", lengthSteps()); });
  doc.getSignalSetting("Cue markers only", section, "Markers").addSignalObserver(function () { run("markers", markerSteps()); });
  doc.getSignalSetting("Record scene 1 into the arranger", section, "Record").addSignalObserver(function () { run("record", recordSteps()); });
  doc.getSignalSetting("Stop and disarm", section, "Stop").addSignalObserver(stopAndDisarm);

  say("version " + VERSION + " loaded");
  log("ready: " + SCORE.tracks.length + " parts, " + SCORE.lengthBeats + " beats at " + SCORE.tempo +
      " bpm, from " + SCORE.source + ". Press Build under this controller in Settings > Controllers.");
}

function flush() {}

function exit() { log("bye"); }

// ---------------------------------------------------------------- the runner

function steps() { return Math.round(SCORE.lengthBeats / SCORE.stepSize); }

function later(ms, fn) {
  host.scheduleTask(function () {
    try { fn(); } catch (e) { host.errorln(TAG + "error: " + e); running = false; }
  }, ms);
}

// Run steps one after another. A step is function(next, fail).
function run(label, list) {
  if (running) { say("still busy with the last action, wait for it to finish"); return; }
  running = true;
  var i = 0;
  log(label + ": " + list.length + " steps");
  function fail(msg) {
    running = false;
    host.errorln(TAG + label + " stopped: " + msg);
    host.showPopupNotification(NAME + ": " + label + " stopped: " + msg);
  }
  function next() {
    if (i >= list.length) { running = false; say(label + " done"); return; }
    var step = list[i++];
    later(0, function () {
      try { step(next, fail); } catch (e) { fail(String(e)); }
    });
  }
  next();
}

// Poll until test() is true, then ok(); after timeout ms, fail().
function waitFor(what, test, timeout, ok, fail) {
  var waited = 0;
  function poll() {
    var done = false;
    try { done = test(); } catch (e) { done = false; }
    if (done) { ok(); return; }
    if (waited >= timeout) { fail("timed out after " + timeout + " ms waiting for " + what); return; }
    waited += POLL_MS;
    later(POLL_MS, poll);
  }
  poll();
}

// ---------------------------------------------------------------- lookups

function count(bank, size) {
  var n = 0;
  for (var i = 0; i < size; i++) if (bank.getItemAt(i).exists().get()) n++;
  return n;
}

function find(bank, size, name) {
  for (var i = 0; i < size; i++) {
    var t = bank.getItemAt(i);
    if (t.exists().get() && t.name().get() === name) return i;
  }
  return -1;
}

function trackIndex(name) { return find(trackBank, MAX_TRACKS, name); }
function fxIndex(name) { return find(fxBank, MAX_FX, name); }

function markerCount() { return count(markers, MAX_MARKERS); }

function markerNamed(name) {
  for (var i = 0; i < MAX_MARKERS; i++) {
    var m = markers.getItemAt(i);
    if (m.exists().get() && m.name().get() === name) return m;
  }
  return null;
}

function near(a, b) { return Math.abs(a - b) < 0.01; }

// ---------------------------------------------------------------- build

function buildSteps() {
  var list = [];
  list.push(function (next) { lengthReport = []; next(); });
  list.push(setTempo);
  var i;
  for (i = 0; i < SCORE.fx.length; i++) list = list.concat(ensureTrack(SCORE.fx[i], true));
  for (i = 0; i < SCORE.tracks.length; i++) list = list.concat(ensureTrack(SCORE.tracks[i], false));
  list.push(setSends);
  list.push(masterGlue);
  for (i = 0; i < SCORE.tracks.length; i++) list = list.concat(writeClip(SCORE.tracks[i]));
  list.push(reportLengths);
  list = list.concat(markerSteps());
  list.push(function (next) {
    transport.setPosition(0);
    log("built " + SCORE.tracks.length + " tracks. Next: press Record, or launch scene 1 with arranger record armed.");
    next();
  });
  return list;
}

function setTempo(next, fail) {
  log("tempo " + SCORE.tempo + " bpm, 4/4");
  transport.tempo().value().setRaw(SCORE.tempo);
  transport.timeSignature().set("4/4");
  waitFor("the tempo", function () { return near(transport.tempo().value().getRaw(), SCORE.tempo); }, 3000, next, fail);
}

// Find a track by name or create it, name it, and load its preset if it has no device yet.
function ensureTrack(spec, isFx) {
  var bank = isFx ? fxBank : trackBank;
  var size = isFx ? MAX_FX : MAX_TRACKS;
  var firstDevice = isFx ? fxFirstDevice : trackFirstDevice;
  var kind = isFx ? "effect track" : "track";
  var index = -1;

  function create(next, fail) {
    index = find(bank, size, spec.name);
    if (index >= 0) { log(kind + " '" + spec.name + "' exists at " + (index + 1) + ", reusing it"); next(); return; }
    var before = count(bank, size);
    if (before >= size) { fail("more than " + size + " " + kind + "s; remove some or raise the bank size"); return; }
    log("creating " + kind + " '" + spec.name + "'");
    if (isFx) app.createEffectTrack(-1); else app.createInstrumentTrack(-1);
    waitFor("the new " + kind, function () { return count(bank, size) === before + 1; }, 5000, function () {
      index = before;           // -1 appends: the new track is the last one
      bank.getItemAt(index).name().set(spec.name);
      waitFor("the name '" + spec.name + "'", function () { return bank.getItemAt(index).name().get() === spec.name; }, 3000, next, fail);
    }, fail);
  }

  function load(next, fail) {
    var device = firstDevice[index];
    if (device.exists().get()) { log("'" + spec.name + "' already has " + device.name().get() + ", keeping it"); next(); return; }
    log("loading " + spec.preset + " on '" + spec.name + "'");
    bank.getItemAt(index).startOfDeviceChainInsertionPoint().insertFile(spec.preset);
    waitFor("the preset on '" + spec.name + "'", function () { return device.exists().get(); }, 15000, function () {
      log("'" + spec.name + "' has " + device.name().get());
      next();
    }, fail);
  }

  return [create, load];
}

function setSends(next, fail) {
  for (var i = 0; i < SCORE.tracks.length; i++) {
    var spec = SCORE.tracks[i];
    var t = trackIndex(spec.name);
    if (t < 0) { fail("track '" + spec.name + "' is missing"); return; }
    var sends = trackBank.getItemAt(t).sendBank();
    for (var j = 0; j < SCORE.fx.length; j++) {
      var name = SCORE.fx[j].name;
      var f = fxIndex(name);
      if (f < 0 || f >= MAX_SENDS) { log("no send to '" + name + "' from '" + spec.name + "'"); continue; }
      var level = spec.sends[name] || 0;
      sends.getItemAt(f).value().set(level);
    }
    log("sends for '" + spec.name + "': " + JSON.stringify(spec.sends));
  }
  next();
}

function masterGlue(next, fail) {
  for (var i = 0; i < MAX_MASTER_DEVICES; i++) {
    var d = masterDevices.getItemAt(i);
    if (d.exists().get() && d.name().get() === SCORE.master.device) {
      log("master already has " + SCORE.master.device + ", keeping it");
      next();
      return;
    }
  }
  var before = count(masterDevices, MAX_MASTER_DEVICES);
  log("loading " + SCORE.master.preset + " on the master");
  master.endOfDeviceChainInsertionPoint().insertFile(SCORE.master.preset);
  waitFor("the master compressor", function () { return count(masterDevices, MAX_MASTER_DEVICES) === before + 1; }, 15000, next, fail);
}

// Replace the track's scene-1 clip with the part.
function writeClip(spec) {
  var index = -1, slots = null, slot = null;

  function clear(next, fail) {
    index = trackIndex(spec.name);
    if (index < 0) { fail("track '" + spec.name + "' is missing"); return; }
    slots = trackBank.getItemAt(index).clipLauncherSlotBank();
    slot = slots.getItemAt(0);
    if (!slot.hasContent().get()) { next(); return; }
    log("replacing the clip on '" + spec.name + "'");
    slots.deleteClip(0);
    waitFor("the old clip to go", function () { return !slot.hasContent().get(); }, 3000, next, fail);
  }

  function create(next, fail) {
    slots.createEmptyClip(0, SCORE.lengthBeats);
    waitFor("a clip on '" + spec.name + "'", function () { return slot.hasContent().get(); }, 3000, next, fail);
  }

  function select(next, fail) {
    selectClip(slot, spec.name, next, fail);
  }

  function size(next, fail) {
    fitLength(spec.name, true, function (ok) {
      if (!ok) log("'" + spec.name + "' is still " + describeLength() + "; see the README's manual fix");
      next();
    });
  }

  function write(next, fail) {
    clip.setStepSize(SCORE.stepSize);
    clip.scrollToKey(0);
    clip.scrollToStep(0);
    clip.clearSteps();
    later(150, function () {
      var notes = spec.notes;
      for (var i = 0; i < notes.length; i++) {
        var n = notes[i];     // [start beat, pitch, velocity, duration beats]
        clip.setStep(0, Math.round(n[0] / SCORE.stepSize), n[1], n[2], n[3]);
      }
      clip.setName(spec.name);
      var starts = {};
      for (i = 0; i < notes.length; i++) starts[Math.round(notes[i][0] / SCORE.stepSize) + ":" + notes[i][1]] = true;
      var expected = Object.keys(starts).length;
      waitFor(expected + " notes on '" + spec.name + "'", function () {
        return clipTrack.name().get() === spec.name && noteStartCount === expected;
      }, 4000, function () {
        log("'" + spec.name + "': " + expected + " notes written");
        confirm();
      }, function () {
        // The step observer can lag; say what we saw and carry on.
        log("'" + spec.name + "': wrote " + expected + " notes, the editor reports " + noteStartCount + " (check this clip)");
        confirm();
      });
      // Writing notes must not have shortened it; set it again if it did.
      function confirm() {
        fitLength(spec.name, false, function (ok) {
          var line = spec.name + ": " + describeLength();
          lengthReport.push({ line: line, ok: ok });
          if (ok) log(line + " (confirmed)"); else host.errorln(TAG + line + ": NOT the full " + SCORE.lengthBeats + " beats");
          next();
        });
      }
    });
  }

  return [clear, create, select, size, write];
}

// ---------------------------------------------------------------- clip length

var lengthReport = [];

// Select a slot's clip in the editor and wait until the cursor clip follows it
// and reports its range.
function selectClip(slot, name, next, fail) {
  slot.select();
  slot.showInEditor();
  waitFor("the editor to show '" + name + "'", function () { return clipTrack.name().get() === name; }, 3000, function () {
    // Give the range values a moment to arrive for this clip (they may not
    // change if it's the same length as the last one, so don't insist).
    waitFor("the clip range of '" + name + "'", function () { return lengthSeen; }, 600, settle, settle);
  }, fail);
  function settle() { later(150, next); }
}

// How long the cursor clip plays: to its play stop without looping, or its
// loop end when looping.
function clipLength() {
  if (clip.isLoopEnabled().get()) return clip.getLoopStart().get() + clip.getLoopLength().get();
  return clip.getPlayStop().get() - clip.getPlayStart().get();
}

function describeLength() {
  var beats = Math.round(clipLength() * 1000) / 1000;
  return beats + " beats (" + Math.round(beats / 4 * 100) / 100 + " bars" +
    (clip.isLoopEnabled().get() ? ", looping " : ", play stop ") +
    (clip.isLoopEnabled().get() ? clip.getLoopLength().get() : clip.getPlayStop().get()) + ")";
}

// The clip plays the whole score once: no loop, play range from 0 to at least L.
function plays() {
  return !clip.isLoopEnabled().get() && near(clip.getPlayStart().get(), 0) && clip.getPlayStop().get() >= SCORE.lengthBeats - 0.01;
}

function fullLength() {
  var L = SCORE.lengthBeats;
  return near(clip.getPlayStart().get(), 0) && clip.getPlayStop().get() >= L - 0.01 &&
    near(clip.getLoopStart().get(), 0) && clip.getLoopLength().get() >= L - 0.01 &&
    !clip.isLoopEnabled().get();
}

// Set the clip's play range and loop to the score's length, read it back, and
// retry. If Bitwig won't take the values and the clip is still empty
// (canDouble), double it with duplicateContent until it's long enough, then
// try once more. done(ok).
function fitLength(name, canDouble, done) {
  var L = SCORE.lengthBeats, attempt = 0, doublings = 0;
  function set() {
    attempt++;
    // Loop range first, then the play range; a play stop past the loop end is
    // clamped in some versions, so stretch the loop before the stop.
    clip.getLoopStart().set(0);
    clip.getLoopLength().set(L);
    clip.getPlayStart().set(0);
    clip.getPlayStop().set(L);
    clip.isLoopEnabled().set(false);
    waitFor("the length of '" + name + "'", fullLength, 700, function () {
      if (attempt > 1 || doublings) log("'" + name + "' took " + attempt + " tries" + (doublings ? " and " + doublings + " doublings" : ""));
      done(true);
    }, retry);
  }
  function retry() {
    log("'" + name + "' reads " + describeLength() + " after try " + attempt);
    if (attempt < 4) { set(); return; }
    if (canDouble && doublings < 8 && Math.max(clip.getPlayStop().get(), clip.getLoopLength().get()) < L - 0.01) {
      double();
      return;
    }
    done(plays());
  }
  function double() {
    var before = Math.max(clip.getPlayStop().get(), clip.getLoopLength().get());
    doublings++;
    log("'" + name + "': doubling the empty clip (" + before + " beats)");
    clip.isLoopEnabled().set(true);
    clip.duplicateContent();
    waitFor("the clip to double", function () {
      return Math.max(clip.getPlayStop().get(), clip.getLoopLength().get()) > before + 0.01;
    }, 1500, function () {
      if (Math.max(clip.getPlayStop().get(), clip.getLoopLength().get()) < L - 0.01 && doublings < 8) { double(); return; }
      attempt = 0;
      set();
    }, function () {
      log("'" + name + "': duplicateContent didn't change the length either");
      done(false);
    });
  }
  set();
}

function lengthSteps() {
  var list = [function (next) { lengthReport = []; next(); }];
  for (var i = 0; i < SCORE.tracks.length; i++) list.push(checkLength(SCORE.tracks[i]));
  list.push(reportLengths);
  return list;
}

function checkLength(spec) {
  return function (next, fail) {
    var t = trackIndex(spec.name);
    if (t < 0) { lengthReport.push({ line: spec.name + ": no track", ok: false }); next(); return; }
    var slot = trackBank.getItemAt(t).clipLauncherSlotBank().getItemAt(0);
    if (!slot.hasContent().get()) { lengthReport.push({ line: spec.name + ": no clip", ok: false }); next(); return; }
    selectClip(slot, spec.name, function () {
      var ok = plays();
      lengthReport.push({ line: spec.name + ": " + describeLength() + (ok ? "" : "  <-- short"), ok: ok });
      log(lengthReport[lengthReport.length - 1].line);
      next();
    }, fail);
  };
}

function reportLengths(next) {
  var short = [], lines = [];
  for (var i = 0; i < lengthReport.length; i++) {
    lines.push(lengthReport[i].line);
    if (!lengthReport[i].ok) short.push(lengthReport[i].line);
  }
  log("clip lengths:\n  " + lines.join("\n  "));
  say(short.length ? short.length + " clip(s) short: " + short.join("; ")
                   : "all " + lines.length + " clips play " + SCORE.lengthBeats + " beats (" + SCORE.lengthBeats / 4 + " bars), e.g. " + lines[0]);
  next();
}

// ---------------------------------------------------------------- cue markers

function markerSteps() {
  var list = [];
  for (var i = 0; i < SCORE.cues.length; i++) list.push(addMarker(SCORE.cues[i]));
  list.push(function (next) { transport.setPosition(0); next(); });
  return list;
}

function addMarker(cue) {
  return function (next, fail) {
    var existing = markerNamed(cue.name);
    if (existing) {
      existing.position().set(cue.beat);
      log("cue marker '" + cue.name + "' moved to beat " + cue.beat + " (" + cue.seconds + " s)");
      next();
      return;
    }
    var before = markerCount();
    transport.setPosition(cue.beat);
    waitFor("the playhead at " + cue.beat, function () { return near(transport.playPosition().get(), cue.beat); }, 1500, add, add);

    function add() {
      transport.addCueMarkerAtPlaybackPosition();
      waitFor("a new cue marker", function () { return markerCount() === before + 1; }, 3000, function () {
        var named = false;
        for (var i = 0; i < MAX_MARKERS && !named; i++) {
          var m = markers.getItemAt(i);
          if (m.exists().get() && near(m.position().get(), cue.beat)) {
            m.name().set(cue.name);
            named = true;
          }
        }
        if (!named) {
          // The playhead didn't land exactly: take the unnamed newcomer nearest the cue.
          var best = null, dist = 1e9;
          for (i = 0; i < MAX_MARKERS; i++) {
            var c = markers.getItemAt(i);
            if (!c.exists().get() || isCue(c.name().get())) continue;
            var d = Math.abs(c.position().get() - cue.beat);
            if (d < dist) { dist = d; best = c; }
          }
          if (best) { best.position().set(cue.beat); best.name().set(cue.name); named = true; }
        }
        log(named ? "cue marker '" + cue.name + "' at beat " + cue.beat + " (" + cue.seconds + " s)"
                  : "added a cue marker at beat " + cue.beat + " but couldn't name it '" + cue.name + "'");
        next();
      }, fail);
    }
  };
}

function isCue(name) {
  for (var i = 0; i < SCORE.cues.length; i++) if (SCORE.cues[i].name === name) return true;
  return false;
}

// ---------------------------------------------------------------- record into the arranger

var savedPreRoll = null;

function recordSteps() {
  return [
    function check(next, fail) {
      for (var i = 0; i < SCORE.tracks.length; i++) {
        var t = trackIndex(SCORE.tracks[i].name);
        if (t < 0) { fail("track '" + SCORE.tracks[i].name + "' is missing; press Build first"); return; }
        if (!trackBank.getItemAt(t).clipLauncherSlotBank().getItemAt(0).hasContent().get()) {
          fail("'" + SCORE.tracks[i].name + "' has no clip in scene 1; press Build first");
          return;
        }
      }
      next();
    },
    function arm(next, fail) {
      transport.stop();
      savedPreRoll = transport.preRoll().get();
      transport.preRoll().set("none");
      transport.setPosition(0);
      transport.isArrangerRecordEnabled().set(true);
      log("arranger record armed at bar 1 (pre-roll was " + savedPreRoll + ")");
      waitFor("arranger record", function () {
        return transport.isArrangerRecordEnabled().get() && !transport.isPlaying().get();
      }, 3000, next, fail);
    },
    function launch(next, fail) {
      log("launching scene 1");
      sceneBank.getScene(0).launch();
      later(300, function () {
        if (!transport.isPlaying().get()) transport.play();
        waitFor("the transport to play", function () { return transport.isPlaying().get(); }, 3000, next, fail);
      });
    },
    function finish(next, fail) {
      var end = SCORE.lengthBeats + 0.5;
      var seconds = Math.ceil(end * 60 / SCORE.tempo) + 30;
      log("recording " + SCORE.lengthBeats + " beats (about " + Math.round(SCORE.lengthBeats * 60 / SCORE.tempo) + " s)");
      waitFor("the end of the score", function () {
        return !transport.isPlaying().get() || transport.playPosition().get() >= end;
      }, seconds * 1000, function () {
        stopAndDisarm();
        log("recorded into the arranger. Check the new clips from bar 1, then File > Export Audio.");
        next();
      }, function (msg) { stopAndDisarm(); fail(msg); });
    }
  ];
}

function stopAndDisarm() {
  transport.stop();
  transport.isArrangerRecordEnabled().set(false);
  transport.returnToArrangement();
  if (savedPreRoll !== null) { transport.preRoll().set(savedPreRoll); savedPreRoll = null; }
  transport.setPosition(0);
  log("stopped, arranger record off, tracks back on the arrangement");
}
